arguments.new_str:
private async Task HandleStep2Submit()
{
    step1Validator?.ClearErrors();
    customValidator?.ClearErrors();

    if (!step2Context.Validate())
        return;

    isSubmitting = true;
    try
    {
        var serverErrors = await AppointmentSvc.ValidatePatientAsync(
            step1.Email!, step1.InsuranceProvider, step2.Doctor, step2.TimeSlot);

        if (serverErrors.Count > 0)
        {
            var step1Fields = new HashSet<string> { nameof(Step1Model.Email), nameof(Step1Model.PatientName),
                nameof(Step1Model.Phone), nameof(Step1Model.InsuranceProvider) };

            var s1Errors = serverErrors.Where(e => step1Fields.Contains(e.Key))
                .ToDictionary(e => e.Key, e => e.Value);
            var s2Errors = serverErrors.Where(e => !step1Fields.Contains(e.Key))
                .ToDictionary(e => e.Key, e => e.Value);

            if (s1Errors.Count > 0) step1Validator!.DisplayErrors(s1Errors);
            if (s2Errors.Count > 0) customValidator!.DisplayErrors(s2Errors);
            return;
        }

        isBooked = true;
    }
    finally
    {
        isSubmitting = false;
    }
}

