1. @page "/book-appointment"
2. @rendermode InteractiveServer
3. @using sv_ccff4760b5f44fe7b54a8cff4f847131.Models
4. @using sv_ccff4760b5f44fe7b54a8cff4f847131.Services
5. @inject AppointmentService AppointmentSvc
6. 
7. <PageTitle>Book Appointment</PageTitle>
8. 
9. <h1>Book an Appointment</h1>
10. 
11. @* ── STEP 1: Patient Information ── *@
12. <h2>Step 1: Patient Information</h2>
13. 
14. <EditForm EditContext="step1Context" OnValidSubmit="HandleStep1Valid" FormName="step1">
15.     <DataAnnotationsValidator />
16.     <CustomValidator @ref="step1Validator" />
17. 
18.     <div>
19.         <label>
20.             Patient Name
21.             <InputText @bind-Value="step1.PatientName" />
22.         </label>
23.         <ValidationMessage For="() => step1.PatientName" />
24.     </div>
25. 
26.     <div>
27.         <label>
28.             Email
29.             <InputText @bind-Value="step1.Email" />
30.         </label>
31.         <ValidationMessage For="() => step1.Email" />
32.     </div>
33. 
34.     <div>
35.         <label>
36.             Phone
37.             <InputText @bind-Value="step1.Phone" />
38.         </label>
39.         <ValidationMessage For="() => step1.Phone" />
40.     </div>
41. 
42.     <div>
43.         <label>
44.             Insurance Provider
45.             <InputSelect @bind-Value="step1.InsuranceProvider">
46.                 <option value="">-- Select --</option>
47.                 <option value="Aetna">Aetna</option>
48.                 <option value="BlueCross">BlueCross</option>
49.                 <option value="Cigna">Cigna</option>
50.                 <option value="UnitedHealth">UnitedHealth</option>
51.                 <option value="None">None</option>
52.             </InputSelect>
53.         </label>
54.         <ValidationMessage For="() => step1.InsuranceProvider" />
55.     </div>
56. 
57.     <button type="submit">Next</button>
58. </EditForm>
59. 
60. @* ── STEP 2: Appointment Details ── *@
61. @if (showStep2)
62. {
63.     <h2>Step 2: Appointment Details</h2>
64. 
65.     <EditForm EditContext="step2Context" OnSubmit="HandleStep2Submit" FormName="step2">
66.         <DataAnnotationsValidator />
67.         <CustomValidator @ref="customValidator" />
68. 
69.         <div>
70.             <label>
71.                 Preferred Doctor
72.                 <InputSelect @bind-Value="step2.Doctor" @bind:after="OnDoctorChanged">
73.                     <option value="">-- Select --</option>
74.                     @foreach (var doc in doctors)
75.                     {
76.                         <option value="@doc">@doc</option>
77.                     }
78.                 </InputSelect>
79.             </label>
80.             <ValidationMessage For="() => step2.Doctor" />
81.         </div>
82. 
83.         <div>
84.             <label>
85.                 Date
86.                 <InputDate @bind-Value="step2.AppointmentDate" @bind:after="OnDateChanged" />
87.             </label>
88.             <ValidationMessage For="() => step2.AppointmentDate" />
89.         </div>
90. 
91.         <div>
92.             <label>
93.                 Time Slot
94.                 <InputSelect @bind-Value="step2.TimeSlot">
95.                     <option value="">-- Select --</option>
96.                     @foreach (var slot in availableSlots)
97.                     {
98.                         <option value="@slot">@slot</option>
99.                     }
100.                 </InputSelect>
101.             </label>
102.             <ValidationMessage For="() => step2.TimeSlot" />
103.         </div>
104. 
105.         <div>
106.             <label>
107.                 Reason for Visit
108.                 <InputTextArea @bind-Value="step2.ReasonForVisit" />
109.             </label>
110.             <ValidationMessage For="() => step2.ReasonForVisit" />
111.         </div>
112. 
113.         <button type="submit" disabled="@isSubmitting">
114.             @(isSubmitting ? "Checking..." : "Check Availability")
115.         </button>
116.     </EditForm>
117. }
118. 
119. @if (isBooked)
120. {
121.     <div>
122.         <strong>Appointment booked successfully!</strong>
123.         <p>@step1.PatientName — @step2.Doctor on @step2.AppointmentDate?.ToString("MMM dd, yyyy") at @step2.TimeSlot</p>
124.     </div>
125. }
126. 
127. @code {
128.     private Step1Model step1 = new();
129.     private Step2Model step2 = new();
130.     private EditContext step1Context = default!;
131.     private EditContext step2Context = default!;
132.     private CustomValidator? step1Validator;
133.     private CustomValidator? customValidator;
134. 
135.     private bool showStep2;
136.     private bool isSubmitting;
137.     private bool isBooked;
138. 
139.     private List<string> doctors = [];
140.     private List<string> availableSlots = [];
141. 
142.     protected override async Task OnInitializedAsync()
143.     {
144.         step1Context = new EditContext(step1);
145.         step2Context = new EditContext(step2);
146.         doctors = await AppointmentSvc.GetDoctorsAsync();
147.     }
148. 
149.     private void HandleStep1Valid()
150.     {
151.         showStep2 = true;
152.     }
153. 
154.     private async Task OnDoctorChanged()
155.     {
156.         step2.TimeSlot = "";
157.         if (!string.IsNullOrEmpty(step2.Doctor) && step2.AppointmentDate.HasValue)
158.         {
159.             availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(step2.Doctor, step2.AppointmentDate.Value);
160.         }
161.         else
162.         {
163.             availableSlots = [];
164.         }
165.     }
166. 
167.     private async Task OnDateChanged()
168.     {
169.         step2.TimeSlot = "";
170.         if (!string.IsNullOrEmpty(step2.Doctor) && step2.AppointmentDate.HasValue)
171.         {
172.             availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(step2.Doctor, step2.AppointmentDate.Value);
173.         }
174.         else
175.         {
176.             availableSlots = [];
177.         }
178.     }
179. 
180.     private async Task HandleStep2Submit()
181.     {
182.         step1Validator?.ClearErrors();
183.         customValidator?.ClearErrors();
184. 
185.         if (!step2Context.Validate())
186.             return;
187. 
188.         isSubmitting = true;
189.         try
190.         {
191.             var serverErrors = await AppointmentSvc.ValidatePatientAsync(
192.                 step1.Email!, step1.InsuranceProvider, step2.Doctor, step2.TimeSlot);
193. 
194.             if (serverErrors.Count > 0)
195.             {
196.                 var step1Fields = new HashSet<string> { nameof(Step1Model.Email), nameof(Step1Model.PatientName),
197.                     nameof(Step1Model.Phone), nameof(Step1Model.InsuranceProvider) };
198. 
199.                 var s1Errors = serverErrors.Where(e => step1Fields.Contains(e.Key))
200.                     .ToDictionary(e => e.Key, e => e.Value);
201.                 var s2Errors = serverErrors.Where(e => !step1Fields.Contains(e.Key))
202.                     .ToDictionary(e => e.Key, e => e.Value);
203. 
204.                 if (s1Errors.Count > 0) step1Validator!.DisplayErrors(s1Errors);
205.                 if (s2Errors.Count > 0) customValidator!.DisplayErrors(s2Errors);
206.                 return;
207.             }
208. 
209.             isBooked = true;
210.         }
211.         finally
212.         {
213.             isSubmitting = false;
214.         }
215.     }
216. }
